<?php
namespace App\Controllers\Admin;use App\Core\Controller;use App\Helpers\AdminAuth;
class Orders extends Controller {public function index():void{$this->handleCors();$this->admin();$rows=$this->db()->query('SELECT o.id,o.order_number,o.status,o.total,o.created_at,c.full_name customer_name,p.status payment_status,d.tracking_number,d.status delivery_status FROM vp_orders o INNER JOIN vp_customers c ON c.id=o.customer_id LEFT JOIN vp_payments p ON p.order_id=o.id LEFT JOIN vp_order_deliveries d ON d.order_id=o.id ORDER BY o.created_at DESC LIMIT 100')->result_array()?:[];$this->success(['items'=>$rows],'Orders loaded');}public function update_status($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$a=$this->admin();$status=(string)($this->getBody()['status']??'');if(!in_array($status,['processing','shipped','completed','cancelled'],true))$this->error('Invalid status',422);$ok=$this->db()->update('vp_orders',['status'=>$status,'updated_at'=>$GLOBALS['now']??date('Y-m-d H:i:s')],['id'=>(int)$id]);if(!$ok)$this->error('Order not found',404);$this->success(null,'Order status updated');}public function save_delivery($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$this->admin();$b=$this->getBody();$order=$this->db()->query('SELECT id FROM vp_orders WHERE id=? LIMIT 1',[(int)$id])->row_array();if(!$order)$this->error('Order not found',404);$now=$GLOBALS['now']??date('Y-m-d H:i:s');$data=['tracking_number'=>trim((string)($b['tracking_number']??''))?:null,'courier_company'=>trim((string)($b['courier_company']??''))?:null,'courier_service'=>trim((string)($b['courier_service']??''))?:null,'status'=>trim((string)($b['status']??'shipped')),'shipped_at'=>$now,'updated_at'=>$now];$existing=$this->db()->query('SELECT id FROM vp_order_deliveries WHERE order_id=? LIMIT 1',[(int)$id])->row_array();if($existing)$this->db()->update('vp_order_deliveries',$data,['id'=>(int)$existing['id']]);else $this->db()->insert('vp_order_deliveries',$data+['order_id'=>(int)$id,'created_at'=>$now]);$this->db()->update('vp_orders',['status'=>'shipped','updated_at'=>$now],['id'=>(int)$id]);$this->success(null,'Delivery saved');}private function admin():array{$a=AdminAuth::user();if(!$a)$this->error('Unauthorized',401);return $a;}}
